// Satori V2 web — translations and language lookup.

function t(lang, key) {
  const dict = STR[lang] || STR.pl;
  if (dict[key]) return dict[key];
  if (STR.en[key]) return STR.en[key];
  return key;
}

function getLang() {
  if (typeof window === 'undefined') return 'pl';
  try { return localStorage.getItem('satori-lang') || 'pl'; } catch { return 'pl'; }
}

